};

function getStyleByDataType(props, dataType, year, activeElectionLevel) {
  const mode = electionPrefixes[activeElectionLevel]?.[year] || "";
  const threshold = activeElectionLevel === "Президент"
  ? presidentTurnoutThresholds
  : turnoutThresholds;
  if (dataType === "Явка") {
    const value = props[`${mode}явка`] || 0;
    const threshold = activeElectionLevel === "Президент"
      ? presidentTurnoutThresholds
      : turnoutThresholds;
    const color = threshold.find(t => value < t.limit)?.color || "#ccc";

    return {
      color: "#000",
      weight: 1,
      fillOpacity: 0.8,
      fillColor: color,
    };
  }

	if (dataType === "Процент испорченных бюллетеней") {
	  const invalidFieldVariants = [
		`${mode}недействительны`,
		`${mode}недействительных`,
		`${mode}недействительные`
	  ];


	const invalidField = invalidFieldVariants.find(f => f in props);
	const value = invalidField ? props[invalidField] : 0;
	const fillColor = invalidThresholds.find(t => value < t.limit)?.color || "#ccc";

    return {
      color: "#000",        // граница УИКов/районов — чёрная
      weight: 1,
      fillOpacity: 0.8,
      fillColor: fillColor, // заливка по проценту испорченных бюллетеней
    };
}}

function getWinnerColorByAdvantage(props, year, activeElectionLevel, activeListType) {
  let candidates = {};
  let colorPalette = {};

  // --- Выбираем кандидатов и палитру ---
  if (activeElectionLevel === "Президент") {
    // Президент 2012
    if (year === 2012) {
      const prefix = electionPrefixes["Президент"][2012] || "";
      if (props.uik_num) {
        for (const key in props) {
          if (key.startsWith(prefix)) {
            const raw = key.replace(prefix, "");
            const name = raw.split("_")[0];
            if (/^[А-ЯЁ]/.test(name)) {
              candidates[name] = props[key] || 0;
            }
          }
        }
      } else {
        candidates = {
          Путин:       props[`${prefix}Путин`]       || 0,
          Зюганов:     props[`${prefix}Зюганов`]     || 0,
          Прохоров:    props[`${prefix}Прохоров`]    || 0,
          Жириновский: props[`${prefix}Жириновский`] || 0,
          Миронов:     props[`${prefix}Миронов`]     || 0,
        };
      }
      colorPalette = presidentColors;
    }
    // Президент 2018
    else if (year === 2018) {
      const prefix = electionPrefixes["Президент"][2018] || "";
      if (props.uik_num) {
        for (const key in props) {
          if (key.startsWith(prefix)) {
            const raw = key.replace(prefix, "");
            const name = raw.split("_")[0];
            if (/^[А-ЯЁ]/.test(name)) {
              candidates[name] = props[key] || 0;
            }
          }
        }
      } else {
        candidates = {
          Путин:       props[`${prefix}Путин`]       || 0,
          Грудинин:    props[`${prefix}Грудинин`]    || 0,
          Жириновский: props[`${prefix}Жириновский`] || 0,
          Собчак:      props[`${prefix}Собчак`]      || 0,
          Сурайкин:    props[`${prefix}Сурайкин`]    || 0,
          Титов:       props[`${prefix}Титов`]       || 0,
          Явлинский:   props[`${prefix}Явлинский`]   || 0,
        };
      }
      colorPalette = president2018Colors;
    }
  }
  // Госдума 2016 (список)
  else if (activeElectionLevel === "Госдума" && year === 2016) {
    const prefix = electionPrefixes["Госдума"][2016] || "";
    for (const key in props) {
      if (!key.startsWith(prefix)) continue;
      const name = key.slice(prefix.length);
      if (name in duma2016Colors) {
        candidates[name] = props[key] || 0;
      }
    }
    colorPalette = duma2016Colors;
  }
  // Госдума 2021
  else if (activeElectionLevel === "Госдума" && year === 2021) {
    const base   = electionPrefixes["Госдума"][2021] || "";     // "2021_duma_"
    const prefix = activeListType === "Округ"
      ? `${base}oik${props.okrug}_`
      : base;

    // собираем голоса по партиям
    const partyScores = {};
    for (const key in props) {
      if (!key.startsWith(prefix) || key.endsWith("_party")) continue;
      const votes = props[key] || 0;
      const party = props[`${key}_party`] || "Неизвестно";
      partyScores[party] = (partyScores[party] || 0) + votes;
    }
    colorPalette = duma2021Colors;

    // определяем победителя и advantage
    const sorted = Object.entries(partyScores).sort((a, b) => b[1] - a[1]);
    if (!sorted.length) return "rgba(204,204,204,0.3)";
    const [winner, top] = sorted[0];
    const second       = sorted[1]?.[1] || 0;
    const advantage    = top - second;

    // прозрачность по defaultAdvantageSteps
    const alpha = defaultAdvantageSteps
      .find(([lim]) => advantage < lim)?.[1] || 1;

    return shadeColor(colorPalette[winner] || "#cccccc", alpha);
  }
  // Мэрские и прочие выборы
  else {
    const prefix = electionPrefixes[activeElectionLevel]?.[year] || "";
    for (const key in props) {
      if (key.startsWith(prefix)) {
        const name = key.replace(prefix, "");
        candidates[name] = props[key] || 0;
      }
    }
    colorPalette = baseColors;
  }

  // --- Общая часть: вычисляем победителя для candidates ---
  const sorted = Object.entries(candidates).sort((a, b) => b[1] - a[1]);
  if (!sorted.length) {
    return "rgba(204,204,204,0.3)";
  }
  const [winner, top] = sorted[0];
  const second       = sorted[1]?.[1] || 0;
  const advantage    = top - second;

  // шаги прозрачности
  const steps = (activeElectionLevel === "Президент" && year === 2018)
    ? advantageStepsPresident2018
    : defaultAdvantageSteps;
  const alpha = steps.find(([limit]) => advantage < limit)?.[1] || 1;

  // возвращаем итоговый цвет
  return shadeColor(colorPalette[winner] || "#cccccc", alpha);
}







